style.css:
@-moz-document domain("youtube.com"), domain("music.youtube.com") {
/* === Accanthis ADF Std Web Font === */
    @font-face {
        font-family: 'Accanthis ADF Std';
        font-style: normal;
        font-weight: 400;
        src: url("https://cdn.jsdelivr.net/gh/hackclub/fonts/AccanthisADFStd-Regular.woff2") format("woff2"),
             url("https://cdn.jsdelivr.net/gh/hackclub/fonts/AccanthisADFStd-Regular.woff") format("woff");
    }

    /* === Global text with neon glow === */
    html, body, ytd-app, ytd-masthead, ytd-page-manager, ytd-watch-flexy,
    #content, #primary, #secondary, #comments, ytd-comment-renderer, 
    ytd-video-primary-info-renderer, ytd-video-secondary-info-renderer,
    ytd-watch-metadata, ytd-rich-grid-renderer, ytd-guide-renderer,
    ytd-mini-guide-entry-renderer, ytd-rich-item-renderer, ytmusic-app,
    ytmusic-player-page, ytmusic-nav-bar, ytmusic-shelf-renderer {
        font-family: 'Accanthis ADF Std', 'Times New Roman', serif !important;
        color: #39FF14 !important;                     /* neon green text */
        text-shadow: 0 0 2px #39FF14, 0 0 5px #39FF14, 0 0 10px #39FF14 !important;
    }

    /* === Video titles glow === */
    #video-title, .title, ytd-video-primary-info-renderer h1 {
        font-family: 'Accanthis ADF Std', serif !important;
        font-weight: 700 !important;
        color: #39FF14 !important;
        text-shadow: 0 0 3px #000, 0 0 5px #39FF14, 0 0 10px #39FF14, 0 0 20px #39FF14 !important;
    }

    /* === Comments neon === */
    #content-text, ytd-comment-renderer #author-text {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #00FFFF !important;  /* cyan neon for contrast */
        text-shadow: 0 0 2px #00FFFF, 0 0 5px #00FFFF, 0 0 8px #00FFFF !important;
    }

    /* === Sidebar and menus glow === */
    ytd-guide-entry-renderer, ytd-mini-guide-entry-renderer, ytd-topbar-menu-button-renderer {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #FF00FF !important;  /* magenta neon */
        text-shadow: 0 0 2px #FF00FF, 0 0 5px #FF00FF, 0 0 10px #FF00FF !important;
    }

    /* === Music titles glow === */
    ytmusic-player-bar, ytmusic-detail-header-renderer, ytmusic-player-page {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #FFD700 !important;  /* gold neon */
        text-shadow: 0 0 2px #FFD700, 0 0 5px #FFD700, 0 0 12px #FFD700 !important;
    }

    /* === Search bar text === */
    input#search, input#search::placeholder {
        font-family: 'Accanthis ADF Std', serif !important;
        font-style: italic !important;
        color: #39FF14 !important;
        text-shadow: 0 0 3px #39FF14, 0 0 7px #39FF14 !important;
    }

    /* === YouTube word/logo glow === */
    ytd-topbar-logo-renderer yt-icon#logo-text,
    *[id*="logo-text"], *[class*="logo-text"],
    ytd-topbar-logo-renderer svg, #logo-icon-container svg, *[id*="logo"] svg {
        fill: #39FF14 !important;
        stroke: #000 !important;
        stroke-width: 1px !important;
        text-shadow: 0 0 5px #39FF14, 0 0 10px #39FF14 !important;
    }
}
